'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var DataView = require( '@stdlib/array/dataview' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var fixtures = require( './fixtures/reference.json' ).cases;


// FUNCTIONS //

/**
* Decodes canonical hexadecimal float64 reference bits.
* @private
* @param {string} s - bits
* @returns {number} value
*/
function decode(s) {
	var v = new DataView(new ArrayBuffer(8));
	v.setUint32(0, parseInt(s.slice(0, 8), 16), false);
	v.setUint32(4, parseInt(s.slice(8), 16), false);
	return v.getFloat64(0, false);
}
/**
* Encodes floating-point bits without losing signed zero.
* @private
* @param {number} x - value
* @returns {string} bits
*/
function bits(x) {
	var v = new DataView(new ArrayBuffer(8));
	var a;
	var b;
	v.setFloat64(0, x, false);
	a = v.getUint32(0, false).toString(16);
	b = v.getUint32(4, false).toString(16);
	return (('00000000' + a).slice(-8) + ('00000000' + b).slice(-8));
}
/**
* Captures a typed view as exact bits or integers.
* @private
* @param {TypedArray} a - view
* @param {boolean} integer - integer dtype
* @returns {Array} snapshot
*/
function snapshot(a, integer) {
	var out = [];
	var i;
	for (i = 0; (i < a.length); i++) {
		out.push(( integer ) ? a[i] : bits(a[i]));
	}
	return out;
}
/**
* Exercises stored triangles, output masks and mathematical factor rows.
* @private
* @param {Object} t - tape assertion object
* @param {Function} f - public kernel
* @returns {void}
*/
function check(t, f) {
	var residual;
	var strides;
	var scale;
	var info;
	var sum;
	var lhs;
	var ra;
	var ca;
	var oa;
	var sp;
	var op;
	var sw;
	var ow;
	var ea;
	var ep;
	var ew;
	var c;
	var n;
	var a;
	var p;
	var r;
	var w;
	var i;
	var j;
	var k;
	var z;
	var h;
	var u;
	for (h = 0; (h < fixtures.length); h++) {
		c = fixtures[h];
		n = c.n;
		u = (c.uplo === 'U') ? 'upper' : 'lower';
		strides = [
			[
				(n + 3),
				1,
				1,
				1
			],
			[
				1,
				(n + 3),
				-2,
				-2
			],
			[
				(-2 * (n + 3)),
				2,
				2,
				3
			],
			[
				2,
				(-2 * (n + 3)),
				-3,
				-1
			],
			[
				-3,
				(-3 * (n + 3)),
				1,
				-3
			]
		];
		for (z = 0; (z < strides.length); z++) {
			ra = strides[z][0];
			ca = strides[z][1];
			sp = strides[z][2];
			sw = strides[z][3];
			oa = ((5 - min(0, ((n - 1) * ra))) - min(0, ((n - 1) * ca)));
			op = (4 - min(0, ((n - 1) * sp)));
			ow = (5 - min(0, (((2 * n) - 1) * sw)));
			a = new Float64Array(new ArrayBuffer((8 * (((oa + max(0, ((n - 1) * ra))) + max(0, ((n - 1) * ca))) + 9))), 16);
			p = new Int32Array(((op + max(0, ((n - 1) * sp))) + 5));
			r = new Int32Array([
				81,
				82,
				83
			]);
			w = new Float64Array(new ArrayBuffer((8 * ((ow + max(0, (((2 * n) - 1) * sw))) + 9))), 16);
			for (i = 0; (i < a.length); i++) {
				a[i] = 117.25;
			}
			for (i = 0; (i < p.length); i++) {
				p[i] = -2147483648;
			}
			for (i = 0; (i < w.length); i++) {
				w[i] = 91.125;
			}
			for (i = 0; (i < n); i++) {
				for (j = 0; (j < n); j++) {
					a[((oa + (i * ra)) + (j * ca))] = decode(c.a[((i * n) + j)]);
				}
			}
			for (i = 0; (i < (2 * n)); i++) {
				w[(ow + (i * sw))] = decode(c.w[i]);
			}
			ea = snapshot(a, false);
			ep = snapshot(p, true);
			ew = snapshot(w, false);
			for (i = 0; (i < n); i++) {
				for (j = 0; (j < n); j++) {
					ea[((oa + (i * ra)) + (j * ca))] = c.expected_a[((i * n) + j)];
				}
				ep[(op + (i * sp))] = c.piv[i];
			}
			for (i = 0; (i < (2 * n)); i++) {
				ew[(ow + (i * sw))] = c.expected_w[i];
			}
			info = f.ndarray(u, n, a, ra, ca, oa, p, sp, op, r, 1, decode(c.tol), w, sw, ow);
			t.strictEqual(info, c.info, (c.name + ' INFO'));
			t.deepEqual(snapshot(a, false), ea, 'factor and ignored cells, guards and padding');
			t.deepEqual(snapshot(p, true), ep, 'complete positive permutation and pivot guards');
			t.deepEqual(snapshot(w, false), ew, 'scratch mutation and guards');
			t.deepEqual(snapshot(r, true), [
				81,
				c.rank,
				83
			], 'only active rank written');

			// Independently reconstruct completed leading rows of P^T*A*P.
			residual = 0;
			scale = 1;
			for (i = 0; (i < c.rank); i++) {
				for (j = 0; (j < n); j++) {
					sum = 0;
					for (k = 0; (k <= min(i, j)); k++) {
						if ((c.uplo === 'U')) { // eslint-disable-line max-depth
							sum += (a[((oa + (k * ra)) + (i * ca))] * a[((oa + (k * ra)) + (j * ca))]);
						} else {
							sum += (a[((oa + (i * ra)) + (k * ca))] * a[((oa + (j * ra)) + (k * ca))]);
						}
					}
					lhs = decode(c.a[((((c.piv[i] - 1) * n) + c.piv[j]) - 1)]);

					// The fixture's opposite triangle is deliberately unrelated storage.
					if ((((c.uplo === 'U') && (c.piv[i] > c.piv[j])) || ((c.uplo === 'L') && (c.piv[i] < c.piv[j])))) {
						lhs = decode(c.a[((((c.piv[j] - 1) * n) + c.piv[i]) - 1)]);
					}
					residual = max(residual, abs((lhs - sum)));
					scale = max(scale, abs(lhs));
				}
			}
			t.ok((residual <= ((2e-13 * n) * scale)), 'independent completed-row reconstruction');
		}
	}
}


// EXPORTS //

module.exports = {
	'check': check,
	'bits': bits,
	'snapshot': snapshot
};
